"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import {
  IconChevronDown,
  IconGlobe,
  IconInfo,
  IconRefresh,
} from "@/components/icons";
import { cn } from "@/lib/utils";

const periods = ["Week", "Month", "Quarter", "Year", "Custom"] as const;

const chipClass =
  "inline-flex h-10 items-center gap-2 rounded-lg border border-icr-border bg-icr-surface px-3 text-sm text-icr-navy";

export function PageHeader() {
  return (
    <div className="flex items-start justify-between gap-4">
      <div>
        <h1 className="m-0 text-[28px] font-bold leading-9 tracking-[-0.02em] text-icr-navy">
          Welcome back, Olivia
        </h1>
        <p className="mt-1 mb-0 text-sm text-icr-muted">
          Summary from Last activity 30 days
        </p>
      </div>
      <div className="inline-flex h-10 items-center gap-3 rounded-lg border border-icr-border bg-icr-surface px-3 text-[13px] text-icr-muted">
        <button
          type="button"
          className="inline-flex items-center gap-1.5 font-medium text-icr-navy"
        >
          <IconRefresh />
          Refresh
        </button>
        <span className="h-4 w-px bg-icr-border" aria-hidden />
        <span>Updated 11:38 PM</span>
      </div>
    </div>
  );
}

function FilterDropdown({
  label,
  open,
  onToggle,
  children,
  active,
  leading,
}: {
  label: ReactNode;
  open: boolean;
  onToggle: () => void;
  children: ReactNode;
  active?: boolean;
  leading?: ReactNode;
}) {
  return (
    <div className="relative">
      <button
        type="button"
        aria-expanded={open}
        onClick={onToggle}
        className={cn(
          chipClass,
          active && "border-icr-orange bg-icr-orange-soft",
        )}
      >
        {leading}
        {label}
        <span
          className={cn(
            "inline-flex transition-transform duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
            open && "rotate-180",
          )}
        >
          <IconChevronDown />
        </span>
      </button>
      <div
        className={cn(
          "absolute top-[calc(100%+8px)] left-0 z-30 min-w-full origin-top transition-all duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
          open
            ? "pointer-events-auto translate-y-0 scale-100 opacity-100"
            : "pointer-events-none -translate-y-1 scale-[0.98] opacity-0",
        )}
      >
        <div className="overflow-hidden rounded-lg border border-icr-border bg-white py-1 shadow-[0_8px_24px_rgba(16,24,40,0.12)]">
          {children}
        </div>
      </div>
    </div>
  );
}

export function FilterBar() {
  const [period, setPeriod] = useState<(typeof periods)[number]>("Month");
  const [regionOpen, setRegionOpen] = useState(false);
  const [deptOpen, setDeptOpen] = useState(false);
  const [productOpen, setProductOpen] = useState(false);
  const [baselineOpen, setBaselineOpen] = useState(false);
  const [fromDate, setFromDate] = useState("09-10-2025");
  const [toDate, setToDate] = useState("09-10-2025");
  const customOpen = period === "Custom";
  const rootRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function onDoc(e: MouseEvent) {
      if (!rootRef.current?.contains(e.target as Node)) {
        setRegionOpen(false);
        setDeptOpen(false);
        setProductOpen(false);
        setBaselineOpen(false);
      }
    }
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);

  return (
    <div ref={rootRef} className="relative flex flex-wrap items-start justify-between gap-4">
      <div className="flex flex-wrap items-center gap-2.5">
        <FilterDropdown
          active
          open={regionOpen}
          onToggle={() => {
            setDeptOpen(false);
            setProductOpen(false);
            setBaselineOpen(false);
            setRegionOpen((v) => !v);
          }}
          leading={<IconGlobe size={14} className="text-icr-orange" />}
          label={
            <>
              <span className="text-[13px] text-icr-muted">Region</span>
              All
            </>
          }
        >
          {["All", "North America", "EMEA", "APAC"].map((item) => (
            <button
              key={item}
              type="button"
              className="flex w-full px-3 py-2 text-left text-sm text-icr-navy hover:bg-[#F8F9FA]"
              onClick={() => setRegionOpen(false)}
            >
              {item}
            </button>
          ))}
        </FilterDropdown>

        <FilterDropdown
          open={deptOpen}
          onToggle={() => {
            setRegionOpen(false);
            setProductOpen(false);
            setBaselineOpen(false);
            setDeptOpen((v) => !v);
          }}
          label="All Department"
        >
          {["All Department", "Intake", "Sales", "Engineering", "Operations"].map(
            (item) => (
              <button
                key={item}
                type="button"
                className="flex w-full px-3 py-2 text-left text-sm text-icr-navy hover:bg-[#F8F9FA]"
                onClick={() => setDeptOpen(false)}
              >
                {item}
              </button>
            ),
          )}
        </FilterDropdown>

        <FilterDropdown
          open={productOpen}
          onToggle={() => {
            setRegionOpen(false);
            setDeptOpen(false);
            setBaselineOpen(false);
            setProductOpen((v) => !v);
          }}
          label="All Products"
        >
          {["All Products", "Quickflange", "Techwrap"].map((item) => (
            <button
              key={item}
              type="button"
              className="flex w-full px-3 py-2 text-left text-sm text-icr-navy hover:bg-[#F8F9FA]"
              onClick={() => setProductOpen(false)}
            >
              {item}
            </button>
          ))}
        </FilterDropdown>
      </div>

      <div className="relative flex flex-wrap items-center gap-2.5">
        <div className="inline-flex overflow-hidden rounded-lg border border-icr-border bg-icr-surface">
          {periods.map((p, i) => (
            <button
              key={p}
              type="button"
              className={cn(
                "h-10 px-3.5 text-sm text-icr-navy transition-colors duration-200",
                i < periods.length - 1 && "border-r border-icr-border",
                period === p &&
                  "bg-icr-orange-soft font-semibold text-icr-orange shadow-[inset_0_0_0_1px_#f6861f]",
              )}
              onClick={() => {
                setPeriod(p);
                setRegionOpen(false);
                setDeptOpen(false);
                setProductOpen(false);
                setBaselineOpen(false);
              }}
            >
              {p}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-2">
          <span className="inline-flex items-center gap-1 text-[13px] text-icr-muted">
            Baseline Median
            <IconInfo />
          </span>
          <FilterDropdown
            open={baselineOpen}
            onToggle={() => {
              setRegionOpen(false);
              setDeptOpen(false);
              setProductOpen(false);
              setBaselineOpen((v) => !v);
            }}
            label="Previous 6 months"
          >
            {[
              "Previous 6 months",
              "Previous 3 months",
              "Previous 12 months",
            ].map((item) => (
              <button
                key={item}
                type="button"
                className="flex w-full px-3 py-2 text-left text-sm text-icr-navy hover:bg-[#F8F9FA]"
                onClick={() => setBaselineOpen(false)}
              >
                {item}
              </button>
            ))}
          </FilterDropdown>
        </div>

        <div
          className={cn(
            "absolute top-[calc(100%+8px)] right-0 z-30 w-[min(420px,90vw)] origin-top-right transition-all duration-300 ease-[cubic-bezier(0.4,0,0.2,1)]",
            customOpen
              ? "pointer-events-auto translate-y-0 scale-100 opacity-100"
              : "pointer-events-none -translate-y-1 scale-[0.98] opacity-0",
          )}
        >
          <div className="flex flex-wrap items-end gap-3 rounded-xl border border-icr-border bg-white p-3 shadow-[0_8px_24px_rgba(16,24,40,0.12)]">
            <label className="flex min-w-[140px] flex-1 flex-col gap-1 text-xs text-icr-muted">
              From
              <span className="inline-flex h-10 items-center gap-2 rounded-lg border border-icr-border bg-white px-3 text-sm text-icr-navy">
                <input
                  type="text"
                  value={fromDate}
                  onChange={(e) => setFromDate(e.target.value)}
                  className="w-full border-none bg-transparent outline-none"
                />
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden>
                  <rect x="3" y="5" width="18" height="16" rx="2" stroke="currentColor" strokeWidth="1.6" />
                  <path d="M3 9h18M8 3v4M16 3v4" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
                </svg>
              </span>
            </label>
            <label className="flex min-w-[140px] flex-1 flex-col gap-1 text-xs text-icr-muted">
              To
              <span className="inline-flex h-10 items-center gap-2 rounded-lg border border-icr-border bg-white px-3 text-sm text-icr-navy">
                <input
                  type="text"
                  value={toDate}
                  onChange={(e) => setToDate(e.target.value)}
                  className="w-full border-none bg-transparent outline-none"
                />
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden>
                  <rect x="3" y="5" width="18" height="16" rx="2" stroke="currentColor" strokeWidth="1.6" />
                  <path d="M3 9h18M8 3v4M16 3v4" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
                </svg>
              </span>
            </label>
            <button
              type="button"
              className="h-10 rounded-lg bg-icr-orange px-4 text-sm font-medium text-white"
              onClick={() => setPeriod("Custom")}
            >
              Apply
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
